// AWS Lambda handler — Node.js 20 runtime
// Triggered by API Gateway POST /orders
// Demonstrates: handler signature, init-outside-handler, stateless design

import { DynamoDBClient, PutItemCommand } from '@aws-sdk/client-dynamodb';
import { SNSClient, PublishCommand } from '@aws-sdk/client-sns';
import { randomUUID } from 'crypto';

// ── Initialisation (runs once per cold start, reused on warm invocations) ──
const dynamo = new DynamoDBClient({ region: process.env.AWS_REGION });
const sns = new SNSClient({ region: process.env.AWS_REGION });

// ── Handler (runs on every invocation) ─────────────────────────────────────
export const handler = async (event, context) => {
  // context.awsRequestId is unique per invocation — useful for idempotency
  console.log('RequestId:', context.awsRequestId);

  try {
    const body = JSON.parse(event.body ?? '{}');

    // Input validation — always validate at the boundary
    if (!body.productId || !body.quantity || body.quantity <= 0) {
      return {
        statusCode: 400,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ error: 'productId and positive quantity are required' }),
      };
    }

    const orderId = randomUUID();
    const userId = event.requestContext?.authorizer?.claims?.sub ?? 'anonymous';
    const timestamp = new Date().toISOString();

    // Persist to DynamoDB — Lambda is stateless; all durable state is external
    await dynamo.send(new PutItemCommand({
      TableName: process.env.ORDERS_TABLE,
      ConditionExpression: 'attribute_not_exists(orderId)', // idempotency guard
      Item: {
        orderId:   { S: orderId },
        productId: { S: String(body.productId) },
        quantity:  { N: String(body.quantity) },
        userId:    { S: userId },
        status:    { S: 'PENDING' },
        createdAt: { S: timestamp },
      },
    }));

    // Publish event — downstream consumers react asynchronously
    await sns.send(new PublishCommand({
      TopicArn: process.env.ORDER_EVENTS_TOPIC,
      Message: JSON.stringify({ orderId, productId: body.productId, quantity: body.quantity, userId }),
      MessageAttributes: {
        eventType: { DataType: 'String', StringValue: 'order.created' },
      },
    }));

    return {
      statusCode: 201,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ orderId, status: 'PENDING', createdAt: timestamp }),
    };
  } catch (err) {
    // ConditionalCheckFailedException = duplicate orderId (race condition handled)
    if (err.name === 'ConditionalCheckFailedException') {
      return {
        statusCode: 409,
        body: JSON.stringify({ error: 'Order already exists' }),
      };
    }
    console.error('Unhandled error:', err);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Internal server error' }),
    };
  }
};
